// film-tv.js — the archive pages' front end (movies / tv / index).
//
// Data contract (generated by `poe film-tv-derive`, committed under
// notes/film-tv/assets/): index.json holds totals + a month → shard map, each
// shard-NNNN.json holds ≤ 200 time-descending records plus count/first_date/
// last_date self-check fields. The default view appends shards lazily; touching
// a filter or a sort loads every shard once (a few MB) so filtering is global.
//
// Pure helpers live in film-tv-core.js (loaded first, node-tested separately).

(function () {
  "use strict";

  const core = window.FilmTvCore || {};
  // element factory from the core module (shared with the chart's script)
  const el = core.el;
  // One page size for every sort mode; month headings are separators *inside* a
  // page, never a page boundary (so an 8-item month flows into the next page).
  const PAGE_SIZE = core.PAGE_SIZE || 12;

  const CATEGORY_LABELS = core.CATEGORY_LABELS || {};
  const SORT_OPTIONS = [
    ["date", "观看时间（新→旧）"],
    ["year", "上映年份（新→旧）"],
    ["rating", "我的评分（高→低）"],
    ["title", "标题"],
  ];

  function state(root) {
    return {
      root,
      kind: root.dataset.kind || "",
      jsonBase: root.dataset.jsonBase || "./assets/",
      index: null,
      coverLocalBase: root.dataset.coverLocalBase || "",
      loaded: new Set(),
      records: [],
      allLoaded: false,
      filters: {},
      sort: "date",
      page: 1,
      // "month" = calendar-style month paging (default); "all" = 12-per-page list
      view: "month",
      monthIndex: 1,
      currentMonth: null,
    };
  }

  async function fetchJson(url) {
    const response = await fetch(url, { cache: "no-cache" });
    if (!response.ok) throw new Error(`${response.status} ${url}`);
    return response.json();
  }

  function shardUrl(app, name) {
    return app.jsonBase + name;
  }

  function banner(app, message, kind) {
    const box = app.root.querySelector(".film-tv__banner");
    if (!box) return;
    box.textContent = message;
    box.className = `film-tv__banner film-tv__banner--${kind || "error"}`;
  }

  async function loadShard(app, name) {
    if (app.loaded.has(name)) return;
    try {
      const shard = await fetchJson(shardUrl(app, name));
      const problem = core.shardProblem(shard, app.index.shard_size);
      if (problem) throw new Error(`${name}: ${problem}`);
      app.loaded.add(name);
      app.records = app.records.concat(shard.items);
      app.records = core.sortRecords(app.records, "date");
    } catch (error) {
      banner(app, `数据分片加载失败：${error.message}（请检查 notes/film-tv/assets/ 是否完整）`);
      throw error;
    }
  }

  async function loadAllShards(app) {
    if (app.allLoaded) return;
    for (const name of shardNames(app)) {
      await loadShard(app, name);
    }
    app.allLoaded = true;
  }

  function visibleRecords(app) {
    const scoped = app.kind
      ? app.records.filter((record) => record.type === app.kind)
      : app.records;
    return core.sortRecords(core.filterRecords(scoped, app.filters), app.sort);
  }

  // --- rendering ------------------------------------------------------------

  // Cover URLs point at the bucket; until an object is uploaded there (or when
  // working offline) the local mirror under docs/assets/bucket/ is tried next, so
  // a local preview shows posters instead of connection errors.
  function coverSources(app, record) {
    const sources = [];
    if (record.cover_url) sources.push(record.cover_url);
    if (record.cover && app.coverLocalBase) sources.push(app.coverLocalBase + record.cover);
    return sources;
  }

  function renderCard(app, record) {
    const card = el("article", "film-tv-card");
    card.dataset.id = record.id;
    card.dataset.slug = record.slug || "";

    const cover = el("div", "film-tv-card__cover");
    const sources = coverSources(app, record);
    if (sources.length) {
      const img = el("img");
      img.loading = "lazy";
      img.decoding = "async";
      let attempt = 0;
      img.src = sources[attempt];
      img.alt = record.title || "";
      img.addEventListener("error", () => {
        attempt += 1;
        if (attempt < sources.length) {
          img.src = sources[attempt];
          return;
        }
        cover.classList.add("is-missing");
        img.remove();
        cover.appendChild(el("span", "film-tv-card__noimage", "无封面"));
      });
      cover.appendChild(img);
    } else {
      cover.classList.add("is-missing");
      cover.appendChild(el("span", "film-tv-card__noimage", "无封面"));
    }
    if (record.pending) cover.appendChild(el("span", "film-tv-card__flag", "待补"));

    const body = el("div", "film-tv-card__body");
    body.appendChild(el("h3", "film-tv-card__title", record.title || record.id));
    const meta = el("p", "film-tv-card__meta");
    const bits = [];
    if (record.year) bits.push(record.year);
    if (record.category) bits.push(CATEGORY_LABELS[record.category] || record.category);
    if (record.runtime) bits.push(`${record.runtime}分钟`);
    if (record.episodes) bits.push(`${record.episodes}集`);
    meta.textContent = bits.join(" · ");
    body.appendChild(meta);

    const line = el("p", "film-tv-card__line");
    if (record.rating) {
      const stars = el("span", "film-tv-card__stars", core.starsOf(record.rating));
      stars.title = `我的评分 ${record.rating}/5`;
      line.appendChild(stars);
    }
    if (record.douban_score) {
      line.appendChild(el("span", "film-tv-card__douban", `豆瓣 ${record.douban_score}`));
    }
    if (record.date) line.appendChild(el("span", "film-tv-card__date", record.date));
    body.appendChild(line);

    if (record.regions && record.regions.length) {
      body.appendChild(el("p", "film-tv-card__regions", record.regions.join(" / ")));
    }
    card.appendChild(cover);
    card.appendChild(body);
    card.addEventListener("click", () => openDetail(record));
    // the card is the archive's primary affordance, so it must be reachable and
    // operable without a mouse (no nested controls, so role=button is safe)
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", `查看 ${record.title || record.id} 的详情`);
    card.addEventListener("keydown", (event) => {
      if (core.isActivationKey(event.key)) {
        event.preventDefault();
        openDetail(record);
      }
    });
    return card;
  }

  function monthSection(month, count, { continued = false } = {}) {
    const section = el("section", "film-tv-month");
    section.dataset.month = month;
    const label = month === "undated" ? "日期未知" : `${month.slice(0, 4)} 年 ${month.slice(5, 7)} 月`;
    const head = el("h2", "film-tv-month__title", label + (continued ? "（续）" : ""));
    head.appendChild(el("span", "film-tv-month__count", `${count} 条`));
    section.appendChild(head);  // heading is its own line: the grid below stays aligned
    section.appendChild(el("div", "film-tv-month__grid"));
    return section;
  }

  function appendCards(app, section, records) {
    const grid = section.querySelector(".film-tv-month__grid");
    for (const record of records) grid.appendChild(renderCard(app, record));
  }

  // Months available for navigation, newest first. When every shard is loaded (a
  // filter is active, or the "all" view) the filtered records are exact; otherwise
  // the derived month index drives the nav, so paging reaches months whose shards
  // have not been fetched yet.
  function monthList(app) {
    if (app.allLoaded || Object.keys(app.filters).length) {
      return core
        .groupByMonth(visibleRecords(app))
        .map(([month, items]) => ({ month, count: items.length }));
    }
    const counts = core.monthCounts(app.index.months, app.kind);
    return Object.keys(counts)
      .filter((month) => /^\d{4}-\d{2}$/.test(month) && counts[month])
      .sort()
      .reverse()
      .map((month) => ({ month, count: counts[month] }));
  }

  // Total records in the current scope, from the index (the loaded shards are
  // only part of the archive until everything has been fetched).
  function scopeTotal(app) {
    if (app.allLoaded || Object.keys(app.filters).length) return visibleRecords(app).length;
    const totals = app.index.totals || {};
    if (app.kind === "movie") return totals.movies || 0;
    if (app.kind === "tv") return totals.tv || 0;
    return totals.records || 0;
  }

  // Month view navigation: the buttons name their destination month, so the
  // direction is never ambiguous (months run newest → oldest).
  function renderMonthNav(app, months, index) {
    const host = app.root.querySelector(".film-tv__pager");
    if (!host) return;
    host.textContent = "";
    const current = months[index - 1].month;
    const older = months[index] ? months[index].month : null;    // newest-first list
    const newer = index > 1 ? months[index - 2].month : null;
    // the nav must fit one line: buttons use the compact YYYY-MM, only the centre
    // label spells the month out
    const monthLabel = (month) =>
      month === "undated" ? "日期未知" : `${month.slice(0, 4)} 年 ${month.slice(5, 7)} 月`;
    const shortLabel = (month) => (month === "undated" ? "日期未知" : month);

    const prev = el("button", "film-tv__page-btn", older ? `‹ ${shortLabel(older)}` : "‹ 上个月");
    prev.type = "button";
    prev.disabled = !older;
    prev.addEventListener("click", () => goToMonthIndex(app, index + 1));
    host.appendChild(prev);

    host.appendChild(
      el("span", "film-tv__page-info", `${monthLabel(current)} · 第 ${index} / ${months.length} 个月`)
    );

    const next = el("button", "film-tv__page-btn", newer ? `${shortLabel(newer)} ›` : "下个月 ›");
    next.type = "button";
    next.disabled = !newer;
    next.addEventListener("click", () => goToMonthIndex(app, index - 1));
    host.appendChild(next);

    const tools = el("span", "film-tv__nav-tools");
    if (index > 1) {
      const latest = el("button", "film-tv__page-btn", "最新");
      latest.type = "button";
      latest.title = "回到最近一个有记录的月份";
      latest.addEventListener("click", () => goToMonthIndex(app, 1));
      tools.appendChild(latest);
    }
    const picker = el("button", "film-tv__page-btn", "选月份");
    picker.type = "button";
    picker.addEventListener("click", () => toggleCalendar(app));
    tools.appendChild(picker);
    const all = el("button", "film-tv__page-btn", "查看全部");
    all.type = "button";
    all.title = "切换成 12 条/页的连续列表";
    all.addEventListener("click", () => {
      app.view = "all";
      app.page = 1;
      renderList(app, { scrollToTop: true });
    });
    tools.appendChild(all);
    host.appendChild(tools);
    host.hidden = false;
  }

  // Month view is a calendar-style *time* view, so entering it always means the
  // date sort: jumping to a month while sorted by rating/title would render an
  // unrelated page-1 list and silently ignore the click.
  function setMonthView(app, index) {
    if (app.sort !== "date") {
      app.sort = "date";
      if (app.sortSelect) app.sortSelect.value = "date";
      banner(app, "已切回「观看时间」排序，按月浏览", "info");
    }
    app.view = "month";
    goToMonthIndex(app, index);
  }

  function goToMonthIndex(app, index) {
    const months = monthList(app);
    if (!months.length) return;
    app.view = "month";
    app.monthIndex = Math.min(Math.max(1, index), months.length);
    app.currentMonth = months[app.monthIndex - 1].month;
    // "undated" has no year: keep the year the calendar is already showing
    app.calendarYear = core.isMonthKey(app.currentMonth)
      ? app.currentMonth.slice(0, 4)
      : app.calendarYear || "";
    syncUrl(app);
    renderList(app, { scrollToTop: true });
  }

  function toggleCalendar(app, force) {
    const panel = app.root.querySelector(".film-tv__calendar");
    if (!panel) return;
    const open = force === undefined ? panel.hidden : force;
    panel.hidden = !open;
    if (open) renderCalendar(app);
  }

  function renderPager(app, { page, pages, label }) {
    const host = app.root.querySelector(".film-tv__pager");
    if (!host) return;
    host.textContent = "";
    const prev = el("button", "film-tv__page-btn", "‹ 上一页");
    prev.type = "button";
    prev.disabled = page <= 1;
    prev.addEventListener("click", () => goToPage(app, page - 1));
    const next = el("button", "film-tv__page-btn", "下一页 ›");
    next.type = "button";
    next.disabled = page >= pages;
    next.addEventListener("click", () => goToPage(app, page + 1));
    host.appendChild(prev);
    host.appendChild(el("span", "film-tv__page-info", label));
    host.appendChild(next);
    host.hidden = pages <= 1;
  }

  // Calendar jump: show the month asked for, or — when it has no records under
  // the current filter — the nearest older month (never an empty page).
  async function goToMonth(app, month) {
    if (!app.allLoaded && (Object.keys(app.filters).length || app.sort !== "date")) {
      await loadAllShards(app);
    }
    const months = monthList(app);
    // exact month when it has records, else the previous (older) one — never an
    // empty view, and never a jump forwards in time
    let index = months.findIndex((entry) => entry.month === month);
    if (index < 0) index = months.findIndex((entry) => entry.month <= month);
    if (index < 0) {
      banner(app, `没有记录：${month} 及更早的月份都没有数据`, "info");
      return;
    }
    banner(app, "", "info");
    setMonthView(app, index + 1);
  }

  // Pull shards until the requested month is **fully** loaded. Shards are
  // contiguous slices, so a month can span two of them: keep pulling while the
  // oldest loaded record still sits in the target month (or newer).
  async function loadShardsUntil(app, month) {
    for (let guard = 0; guard < 200; guard += 1) {
      const records = app.records;
      const last = records.length ? core.monthKey(records[records.length - 1].date) : "";
      if (last && last < month) return;
      const before = app.records.length;
      await loadShard(app, nextShardName(app));
      if (app.records.length === before) return;  // no more shards
    }
  }

  async function goToPage(app, page) {
    app.page = Math.max(1, page);
    // Time order reads shards lazily: a page may live in a shard we have not
    // fetched yet, so pull shards until the month is on hand.
    if (!app.allLoaded) {
      // pages are index windows: make sure the window is loaded
      for (let guard = 0; guard < 60; guard += 1) {
        const needed = core.pageTarget(visibleRecords(app), app.page, PAGE_SIZE);
        if (needed <= app.records.length) break;
        const before = app.records.length;
        await loadShard(app, nextShardName(app));
        if (app.records.length === before) break;
      }
    }
    renderList(app, { scrollToTop: true });
  }

  function renderList(app, { reset = false, scrollToTop = false } = {}) {
    const list = app.root.querySelector(".film-tv__list");
    const records = visibleRecords(app);
    if (reset) app.page = 1;
    list.textContent = "";

    if (!records.length) {
      app.currentMonth = null;
      app.page = 1;
      renderEmptyState(
        app,
        Object.keys(app.filters).length ? "当前筛选没有结果" : "归档里还没有记录"
      );
      const emptyCounter = app.root.querySelector(".film-tv__count");
      if (emptyCounter) emptyCounter.textContent = "共 0 条";
      app.pageMonths = new Set();
      renderPager(app, { page: 1, pages: 1, label: "第 1 / 1 页" });
      highlightCalendar(app);
      renderChips(app);
      return;
    }

    if (app.view === "month" && app.sort === "date") {
      // Calendar-style view: one month per "screen", paging through the months
      // that have records under the current filter. The list is replaced, never
      // appended to (paging months must not stack month sections).
      list.textContent = "";
      const months = monthList(app);
      if (!months.length) {
        app.currentMonth = null;
        app.pageMonths = new Set();
        renderEmptyState(app, "当前筛选没有结果");
        const emptyCounter = app.root.querySelector(".film-tv__count");
        if (emptyCounter) emptyCounter.textContent = "共 0 条";
        renderPager(app, { page: 1, pages: 1, label: "第 1 / 1 页" });
        highlightCalendar(app);
        renderChips(app);
        return;
      }
      app.monthIndex = Math.min(Math.max(1, app.monthIndex), months.length);
      const month = months[app.monthIndex - 1].month;
      const expected = months[app.monthIndex - 1].count;
      const items = records.filter((record) => core.monthKey(record.date) === month);
      if (!app.allLoaded && items.length < expected) {
        // The index says this month has more records than we hold: a month can span
        // two shards. Pull them, then render again. One attempt per (month, loaded
        // count) — if the shards cannot supply more, render what we have instead of
        // retrying, so a broken shard cannot spin here.
        const key = `${month}:${items.length}`;
        if (app.pendingMonthLoad !== key) {
          app.pendingMonthLoad = key;
          loadShardsUntil(app, month).then(() => renderList(app));
          return;
        }
      }
      const section = monthSection(month, items.length);
      appendCards(app, section, core.sortRecords(items, "date"));
      list.appendChild(section);
      app.currentMonth = month;
      app.pageMonths = new Set([month]);
      const counter = app.root.querySelector(".film-tv__count");
      if (counter) {
        counter.textContent = `共 ${scopeTotal(app)} 条 · 本月 ${items.length} 条`;
      }
      renderMonthNav(app, months, app.monthIndex);
      highlightCalendar(app);
      renderChips(app);
      if (scrollToTop) list.scrollIntoView({ behavior: "smooth", block: "start" });
      return;
    }

    const pages = Math.max(1, Math.ceil(records.length / PAGE_SIZE));
    app.page = Math.min(Math.max(1, app.page), pages);
    const startIndex = (app.page - 1) * PAGE_SIZE;
    const slice = records.slice(startIndex, startIndex + PAGE_SIZE);

    // month totals across the whole (filtered) list, for the heading counts
    const monthTotals = new Map();
    for (const record of records) {
      const key = core.monthKey(record.date);
      monthTotals.set(key, (monthTotals.get(key) || 0) + 1);
    }
    // did the first month of this page continue from the previous page?
    const firstMonth = core.monthKey(slice[0].date);
    const continued = app.sort === "date"
      && startIndex > 0
      && core.monthKey(records[startIndex - 1].date) === firstMonth;

    if (app.sort === "date") {
      // group the page's rows by month and keep the month headings as separators
      let section = null;
      let seeded = false;
      for (const record of slice) {
        const key = core.monthKey(record.date);
        if (!section || section.dataset.month !== key) {
          section = monthSection(key, monthTotals.get(key) || 0, {
            continued: continued && !seeded,
          });
          list.appendChild(section);
          seeded = true;
        }
        appendCards(app, section, [record]);
      }
      app.currentMonth = firstMonth;
      app.pageMonths = new Set(slice.map((record) => core.monthKey(record.date)));
    } else {
      const section = monthSection("all", records.length);
      const title = section.querySelector(".film-tv-month__title");
      title.firstChild.textContent = "全部记录";
      appendCards(app, section, slice);
      list.appendChild(section);
      app.currentMonth = null;
      app.pageMonths = new Set();
    }

    const lastIndex = startIndex + slice.length - 1;
    renderPager(app, {
      page: app.page,
      pages,
      label: `第 ${app.page} / ${pages} 页（每页 ${PAGE_SIZE} 条）`,
    });
    const pager = app.root.querySelector(".film-tv__pager");
    if (pager) {
      const monthView = el("button", "film-tv__page-btn", "按月浏览");
      monthView.type = "button";
      monthView.title = "切换成按月翻页的日历视图";
      monthView.addEventListener("click", () => setMonthView(app, 1));
      const tools = el("span", "film-tv__nav-tools");
      tools.appendChild(monthView);
      pager.appendChild(tools);
    }
    const counter = app.root.querySelector(".film-tv__count");
    if (counter) {
      counter.textContent =
        `显示第 ${startIndex + 1}–${lastIndex + 1} 条 / 共 ${records.length} 条`;
    }
    highlightCalendar(app);
    renderChips(app);
    if (scrollToTop) list.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  function renderEmptyState(app, message) {
    const list = app.root.querySelector(".film-tv__list");
    list.appendChild(el("p", "film-tv__empty", message));
  }

  function renderCalendar(app) {
    const host = app.root.querySelector(".film-tv__calendar");
    if (!host || !app.index) return;
    // One year at a time, rotated with ← / → (a wall of every year is unusable
    // once the archive spans two decades). Counts follow the active filter when
    // every shard is loaded, else the index's per-type month counts.
    const counts = {};
    if (app.allLoaded) {
      for (const [month, items] of core.groupByMonth(visibleRecords(app))) {
        counts[month] = items.length;
      }
    } else {
      Object.assign(counts, core.monthCounts(app.index.months, app.kind));
    }
    // `core.calendarYears` ignores the "undated" pseudo-month: slicing the key
    // instead would offer "unda 年" (and then select it on the first render)
    const years = core.calendarYears(counts);
    if (!years.length) {
      host.textContent = "";
      return;
    }
    const wanted = (app.currentMonth || app.wantedMonth || "").slice(0, 4);
    if (!app.calendarYear || !years.includes(String(app.calendarYear))) {
      app.calendarYear = years.includes(wanted) ? wanted : years[years.length - 1];
    }
    const year = app.calendarYear;
    const position = years.indexOf(String(year));
    const countsFor = (month) => counts[month] || 0;

    host.textContent = "";
    const nav = el("div", "film-tv-calendar__nav");
    const older = el("button", "film-tv-calendar__year-btn", "‹");
    older.type = "button";
    older.title = "上一年";
    older.disabled = position <= 0;
    older.addEventListener("click", () => {
      app.calendarYear = years[position - 1];
      renderCalendar(app);
    });
    const newer = el("button", "film-tv-calendar__year-btn", "›");
    newer.type = "button";
    newer.title = "下一年";
    newer.disabled = position >= years.length - 1;
    newer.addEventListener("click", () => {
      app.calendarYear = years[position + 1];
      renderCalendar(app);
    });
    nav.appendChild(older);
    nav.appendChild(el("span", "film-tv-calendar__year-label", `${year} 年`));
    nav.appendChild(newer);
    const hint = el("span", "film-tv-calendar__hint", `${years.length} 个年份`);
    nav.appendChild(hint);
    host.appendChild(nav);

    const grid = el("div", "film-tv-calendar__months");
    for (let month = 1; month <= 12; month += 1) {
      const key = `${year}-${String(month).padStart(2, "0")}`;
      const count = countsFor(key);
      const cell = el("button", "film-tv-calendar__cell");
      cell.type = "button";
      cell.dataset.month = key;
      cell.appendChild(
        el("span", "film-tv-calendar__month-name", String(month).padStart(2, "0"))
      );
      cell.appendChild(el("span", "film-tv-calendar__count", count ? String(count) : "·"));
      cell.title = count
        ? `${key} · ${count} 条`
        : `${key} · 没有记录（跳到上一个有记录的月份）`;
      if (!count) cell.classList.add("is-empty");
      cell.addEventListener("click", () => goToMonth(app, key));
      grid.appendChild(cell);
    }
    host.appendChild(grid);
    highlightCalendar(app);
  }

  function highlightCalendar(app) {
    const months = app.pageMonths || new Set(app.currentMonth ? [app.currentMonth] : []);
    for (const cell of app.root.querySelectorAll(".film-tv-calendar__cell[data-month]")) {
      // every month the current page covers stays highlighted, so a jump to a
      // month that shares its page with others is still visible
      cell.classList.toggle("is-current", months.has(cell.dataset.month));
    }
  }

  // --- controls -------------------------------------------------------------

  function buildControls(app) {
    const host = app.root.querySelector(".film-tv__filters");
    if (!host) return;
    host.textContent = "";

    const search = el("input", "film-tv__search");
    search.type = "search";
    search.placeholder = "搜索片名 / 原名 / 导演 / 演员";
    search.addEventListener("input", () => {
      app.filters.q = search.value.trim();
      refresh(app, { reloadAll: true, debounce: true });
    });
    host.appendChild(search);

    // [filter key, label, record field (or derived facet), value formatter]
    // No tag filter: the archived Douban tags are legacy/inaccurate.
    const selects = [
      ["category", "类型", "category", (value) => CATEGORY_LABELS[value] || value],
      ["region", "地区", "regions"],
      ["decade", "年代", "decade"],
      ["rating", "我的评分", "rating"],
    ];
    app.selects = {};
    for (const [key, label, facet, formatValue] of selects) {
      const wrap = el("label", "film-tv__select");
      wrap.appendChild(el("span", "film-tv__select-label", label));
      const select = el("select");
      select.dataset.filter = key;
      select.appendChild(new Option("全部", ""));
      wrap.appendChild(select);
      host.appendChild(wrap);
      app.selects[key] = { select, facet, formatValue };
      select.addEventListener("change", () => {
        if (select.value) app.filters[key] = select.value;
        else delete app.filters[key];
        refresh(app, { reloadAll: true });
      });
    }

    const sortWrap = el("label", "film-tv__select");
    sortWrap.appendChild(el("span", "film-tv__select-label", "排序"));
    const sortSelect = el("select");
    for (const [value, text] of SORT_OPTIONS) sortSelect.appendChild(new Option(text, value));
    sortSelect.addEventListener("change", () => {
      app.sort = sortSelect.value;
      // month view only exists in time order: a different sort is a paged list
      if (app.sort !== "date") app.view = "all";
      app.page = 1;
      refresh(app, { reloadAll: true });
    });
    sortWrap.appendChild(sortSelect);
    host.appendChild(sortWrap);
    app.sortSelect = sortSelect;

    const clear = el("button", "film-tv__clear", "清除筛选");
    clear.type = "button";
    clear.addEventListener("click", () => {
      app.filters = {};
      syncControls(app);
      refresh(app, { reloadAll: true });
    });
    host.appendChild(clear);
  }

  function fillFacets(app) {
    if (!app.selects) return;
    const scope = app.kind ? app.records.filter((r) => r.type === app.kind) : app.records;
    for (const [, { select, facet, formatValue }] of Object.entries(app.selects)) {
      const current = select.value;
      select.textContent = "";
      select.appendChild(new Option("全部", ""));
      if (facet === "rating") {
        // a rating is a minimum threshold, not a value list: "4 星以上"
        for (const stars of [5, 4, 3, 2, 1]) {
          select.appendChild(new Option(`${stars} 星以上`, String(stars)));
        }
      } else {
        for (const [value, count] of core.facetCounts(scope, facet)) {
          const label = formatValue ? formatValue(value) : value;
          select.appendChild(new Option(`${label} (${count})`, value));
        }
      }
      select.value = current;
    }
    if (app.sortSelect) app.sortSelect.value = app.sort;
  }

  // Chips showing the active filters, each removable. The person chip is set by
  // clicking a name in the detail dialog.
  const FILTER_LABELS = {
    q: "搜索",
    category: "类型",
    region: "地区",
    decade: "年代",
    rating: "评分",
    person: "影人",
    status: "状态",
  };

  function renderChips(app) {
    syncUrl(app);

    const host = app.root.querySelector(".film-tv__chips");
    if (!host) return;
    host.textContent = "";
    const entries = Object.entries(app.filters).filter(([, value]) => value);
    host.hidden = entries.length === 0;
    for (const [key, value] of entries) {
      const chip = el("button", "film-tv__chip");
      chip.type = "button";
      const label = FILTER_LABELS[key] || key;
      const shown = key === "q"
        ? `“${value}”`
        : key === "category"
          ? CATEGORY_LABELS[value] || value
          : key === "rating"
            ? `${value} 星以上`
            : value;
      chip.textContent = `${label}：${shown} ✕`;
      chip.addEventListener("click", () => {
        delete app.filters[key];
        if (key === "q") {
          const search = app.root.querySelector(".film-tv__search");
          if (search) search.value = "";
        }
        syncControls(app);
        refresh(app, { reloadAll: true });
      });
      host.appendChild(chip);
    }
  }

  function syncControls(app) {
    if (app.selects) {
      for (const key of Object.keys(app.selects)) {
        app.selects[key].select.value = app.filters[key] || "";
      }
    }
    highlightCalendar(app);
    renderChips(app);
  }

  // Keep the shareable bits of the view in the URL (person filter + month).
  function syncUrl(app) {
    const url = new URL(window.location.href);
    if (app.filters.person) url.searchParams.set("person", app.filters.person);
    else url.searchParams.delete("person");
    if (app.view === "month" && app.currentMonth) url.searchParams.set("month", app.currentMonth);
    else url.searchParams.delete("month");
    history.replaceState(null, "", url);
  }

  // --- detail dialog --------------------------------------------------------

  function openDetail(record) {
    const dialog = document.querySelector(".film-tv-dialog");
    if (!dialog) return;
    const cover = dialog.querySelector(".film-tv-dialog__cover");
    cover.textContent = "";
    if (record.cover_url) {
      const img = el("img");
      img.src = record.cover_url;
      img.alt = record.title || "";
      cover.appendChild(img);
    }
    dialog.querySelector(".film-tv-dialog__title").textContent = record.title || record.id;
    const original = record.original_title || "";
    const subtitle = dialog.querySelector(".film-tv-dialog__original");
    subtitle.textContent = original && original !== record.title ? original : "";
    subtitle.hidden = !subtitle.textContent;

    const list = dialog.querySelector(".film-tv-dialog__facts");
    list.textContent = "";
    // the rows (and which of them are people) come from the node-tested core
    for (const fact of core.dialogFacts(record)) {
      const item = el("div", "film-tv-dialog__fact");
      item.appendChild(el("dt", null, fact.label));
      const dd = el("dd");
      if (fact.people.length) {
        // one person per line; see .film-tv-dialog__person for why this is a
        // stack of block buttons and not a <ul>
        for (const name of fact.people) {
          const button = el("button", "film-tv-dialog__person", name);
          button.type = "button";
          button.addEventListener("click", () => {
            dialog.close();
            filterByPerson(name);
          });
          dd.appendChild(button);
        }
      } else {
        dd.textContent = fact.value;
      }
      item.appendChild(dd);
      list.appendChild(item);
    }

    const comment = dialog.querySelector(".film-tv-dialog__comment");
    comment.textContent = "";
    if (record.comment) {
      comment.appendChild(el("h4", null, "豆瓣短评"));
      comment.appendChild(el("p", null, record.comment));
    }
    if (record.review) {
      comment.appendChild(el("h4", null, "我的影评"));
      const lines = String(record.review).split("\n");
      for (const line of lines) comment.appendChild(el("p", null, line));
    }
    const link = dialog.querySelector(".film-tv-dialog__link");
    if (record.url) {
      link.href = record.url;
      link.hidden = false;
    } else {
      link.hidden = true;
    }
    dialog.dataset.slug = record.slug || "";
    if (dialog.showModal) dialog.showModal();
    else dialog.setAttribute("open", "open");
    const url = new URL(window.location.href);
    if (record.slug) url.searchParams.set("id", record.slug);
    history.replaceState(null, "", url);
  }

  // set by init() so the dialog can reach the page's filter state
  let activeApp = null;

  function filterByPerson(name) {
    if (!activeApp) return;
    activeApp.filters.person = name;
    syncControls(activeApp);
    refresh(activeApp, { reloadAll: true });
    banner(activeApp, `只看「${name}」的作品（点筛选条上的 ✕ 取消）`, "info");
  }

  function wireDialog() {
    const dialog = document.querySelector(".film-tv-dialog");
    if (!dialog) return;
    dialog.querySelector(".film-tv-dialog__close").addEventListener("click", () => dialog.close());
    dialog.addEventListener("close", () => {
      const url = new URL(window.location.href);
      url.searchParams.delete("id");
      history.replaceState(null, "", url);
    });
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) dialog.close();
    });
  }

  // --- wiring ---------------------------------------------------------------

  let debounceTimer = null;

  function refresh(app, { reloadAll, reset = true, debounce = false } = {}) {
    const run = async () => {
      try {
        if (reloadAll || Object.keys(app.filters).length || app.sort !== "date") {
          await loadAllShards(app);
        } else if (!app.loaded.size) {
          await loadShard(app, firstShardName(app));
        }
        fillFacets(app);
        if (reset) app.monthIndex = 1;
        renderList(app, { reset });
        if (reset && app.wantedMonth) {
          const index = monthList(app).findIndex((entry) => entry.month === app.wantedMonth);
          app.wantedMonth = "";
          if (index >= 0) {
            // `?month=` deep link: same state as setMonthView, but rendered without
            // scrolling (the page must stay at the top on load)
            app.view = "month";
            app.monthIndex = index + 1;
            renderList(app, {});
          }
        }
        if (reset) {
          const deepLink = new URLSearchParams(window.location.search).get("id");
          const match = deepLink
            ? app.records.find((record) => record.slug === deepLink)
            : null;
          if (match) openDetail(match);
        }
      } catch (error) {
        // banner() already reported the details
        console.error("film-tv:", error);
      }
    };
    if (debounce) {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(run, 200);
    } else {
      run();
    }
  }

  // The shard list comes from index.json's explicit `shards` array. Deriving it
  // from `months` would skip shards: a month only records the shard holding its
  // first record, so a shard whose records all belong to an already-started month
  // never appears there (and the records in it would silently go missing).
  function shardNames(app) {
    const explicit = app.index.shards;
    if (Array.isArray(explicit) && explicit.length) return [...explicit].sort();
    const derived = Object.values(app.index.months || {})
      .map((info) => info.shard)
      .filter(Boolean);
    return [...new Set(derived)].sort();
  }

  function firstShardName(app) {
    return shardNames(app)[0] || "shard-0001.json";
  }

  async function init(root) {
    const app = state(root);
    activeApp = app;
    // debug handle: lets the headless verification scripts read paging state
    // (loaded shards, current month, pending loads) straight from the page
    window.filmTvApp = app;
    const params = new URLSearchParams(window.location.search);
    const person = params.get("person");
    if (person) app.filters.person = person;
    app.wantedMonth = params.get("month") || "";
    wireDialog();
    try {
      app.index = await core.fetchJsonOnce(app.jsonBase + "index.json");
    } catch (error) {
      banner(app, `索引加载失败：${error.message}`);
      return;
    }
    banner(app, "", "info");
    // the month picker is visible by default (it doubles as the year/month
    // overview); the 「选月份」 button collapses it away again
    toggleCalendar(app, true);
    buildControls(app);
    await refresh(app, { reloadAll: false });
  }

  function nextShardName(app) {
    const names = shardNames(app);
    return names.find((name) => !app.loaded.has(name)) || names[names.length - 1];
  }

  function boot() {
    for (const root of document.querySelectorAll(".film-tv[data-kind]")) {
      init(root);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
